package com.foodflow.coupon.entity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="coupons",uniqueConstraints=@UniqueConstraint(columnNames="code")) @Getter @Setter @NoArgsConstructor public class Coupon {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,unique=true) private String code; @Column(nullable=false,precision=5,scale=2) private BigDecimal discountPercent; @Column(nullable=false) private int maxUses; @Column(nullable=false) private int usedCount=0; @Column(nullable=false) private LocalDateTime expiresAt; @Column(nullable=false) private boolean active=true;}
